/// A mask with its light and dark fill.
pub type Layer = (&'static Icon, &'static str, &'static str);

pub fn layers(driver: &str) -> Option<&'static [Layer]> {
    Some(match driver {
        "cursor" => {
            static L: &[Layer] = &[(&CURSOR_0, "#26251E", "#EDECEC")];
            L
        }
        "grok" => {
            static L: &[Layer] = &[(&GROK_0, "#0F0F0F", "#F5F5F5"), (&GROK_1, "#0F0F0F", "#F5F5F5")];
            L
        }
        "kiro" => {
            static L: &[Layer] = &[(&KIRO_0, "#9046FF", "#9046FF"), (&KIRO_1, "#FFFFFF", "#FFFFFF"), (&KIRO_2, "#000000", "#000000"), (&KIRO_3, "#000000", "#000000")];
            L
        }
        "pi" => {
            static L: &[Layer] = &[(&PI_0, "#0F0F0F", "#F5F5F5"), (&PI_1, "#0F0F0F", "#F5F5F5")];
            L
        }
        "fx" => {
            static L: &[Layer] = &[(&FX_0, "#0F0F0F", "#F5F5F5")];
            L
        }
        "muse" => {
            static L: &[Layer] = &[(&MUSE_0, "#0081fb", "#0081fb"), (&MUSE_1, "#0073ee", "#0073ee"), (&MUSE_2, "#0064e0", "#0064e0")];
            L
        }
        "antigravity" => {
            static L: &[Layer] = &[(&ANTIGRAVITY_0, "#658ab9", "#658ab9"), (&ANTIGRAVITY_1, "#2f8af1", "#2f8af1"), (&ANTIGRAVITY_2, "#3a87fc", "#3a87fc"), (&ANTIGRAVITY_3, "#3391db", "#3391db"), (&ANTIGRAVITY_4, "#4a88f5", "#4a88f5"), (&ANTIGRAVITY_5, "#eb613d", "#eb613d"), (&ANTIGRAVITY_6, "#3e9cbe", "#3e9cbe"), (&ANTIGRAVITY_7, "#55a59b", "#55a59b"), (&ANTIGRAVITY_8, "#75af77", "#75af77"), (&ANTIGRAVITY_9, "#d39b36", "#d39b36"), (&ANTIGRAVITY_10, "#6184e2", "#6184e2"), (&ANTIGRAVITY_11, "#a0b152", "#a0b152"), (&ANTIGRAVITY_12, "#cc655d", "#cc655d"), (&ANTIGRAVITY_13, "#787cc0", "#787cc0"), (&ANTIGRAVITY_14, "#ab717c", "#ab717c"), (&ANTIGRAVITY_15, "#90769f", "#90769f"), (&ANTIGRAVITY_16, "#5188ca", "#5188ca")];
            L
        }
        _ => return None,
    })
}
